import {BatchQueue} from "./BatchQueue.js";
import {ServerExtension} from "./ServerExtension.js";
import {ServerSessionExtension} from "./ServerSessionExtension.js";

export class AcknowledgedMessagesExtension extends ServerExtension {
    incoming(cometd, session, message, callback) {
        if (message.channel === "/meta/handshake") {
            const ext = message.ext;
            if (ext && ext.ack === true) {
                cometd._log("cometd.server.ext.ack", "enabled acknowledged messages extension for session", session.id);
                session.addExtension(new SessionExtension(cometd, session));
            }
        }
        super.incoming(cometd, session, message, callback);
    }
}

class SessionExtension extends ServerSessionExtension {
    #queue = new BatchQueue();
    #batches = {};
    #cometd;

    constructor(cometd, session) {
        super();
        this.#cometd = cometd;
        session._metaConnectDeliveryOnly = true;
        session.addListener("queueOffer", (s, m) => this.#queueOffer(s, m));
        session.addListener("queueDrain", (s, m, r) => this.#queueDrain(s, m, r));
    }

    incoming(session, message, callback) {
        if (message.channel === "/meta/connect") {
            const ext = message.ext;
            if (ext) {
                const ack = ext.ack;
                if (typeof ack === "number") {
                    // Clear the queue up to the acknowledged batch.
                    this.#queue.clearToBatch(ack);
                    this.#cometd._log("cometd.session.ext.ack", "processing batch: client:", ack, "server:", this.#queue.batch, "session", session.id);
                    if (!session._hasMessages && this.#queue.size > 0) {
                        const advice = message.advice || {};
                        message.advice = advice;
                        advice.timeout = 0;
                        this.#cometd._log("cometd.session.ext.ack", "forcing advice:{timeout:0} session", session.id);
                    }
                }
            }
        }
        super.incoming(session, message, callback);
    }

    outgoing(sender, session, message, callback) {
        if (message.channel === "/meta/handshake") {
            const hsExt = message.ext || {};
            message.ext = hsExt;
            hsExt.ack = true;
        } else if (message.channel === "/meta/connect") {
            // Close the batch.
            const batch = this.#queue.batch++;
            this.#batches[message.id] = batch;
            const cnExt = message.ext || {};
            message.ext = cnExt;
            cnExt.ack = batch;
        }
        super.outgoing(sender, session, message, callback);
    }

    #queueOffer(session, message) {
        this.#queue.offer(message);
        this.#cometd._log("cometd.session.ext.ack", "stored at batch", this.#queue.batch, "session", session.id, message);
    }

    #queueDrain(session, messageQueue, replies) {
        let metaConnectId;
        for (let i = 0; i < replies.length; ++i) {
            const reply = replies[i];
            if (reply.channel === "/meta/connect") {
                metaConnectId = reply.id;
                break;
            }
        }
        if (metaConnectId) {
            const batch = this.#batches[metaConnectId];
            delete this.#batches[metaConnectId];
            const messageBatch = this.#queue.sliceToBatch(batch);
            this.#cometd._log("cometd.session.ext.ack", "replacing", messageQueue.length, "messages with", messageBatch.length, "un-acked messages from batch", batch, "session", session.id);
            // Clear the queue and add the batch of message to send.
            messageQueue.splice(0, messageQueue.length);
            messageQueue.push.apply(messageQueue, messageBatch);
        }
    }
}
